def main():
    assert set(P.keys()) == set(IDS), "id 集與本批不一致"
    assert len(P) == 20, "案例數不為 20"
    n = 0
    for cid in IDS:
        d = P[cid]
        rec = {"case_id": cid,
               "prediction_text": d["prediction_text"],
               "basis": d["basis"],
               "confidence": d["confidence"],
               "trigger": d["trigger"]}
        with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        n += 1
    assert n == 20, "寫出文件數不為 20"
    cm = sum(1 for cid in IDS if P[cid]["trigger"]["changed_main"])
    ru = sum(1 for cid in IDS if P[cid]["trigger"]["reserve_used"])
    dp = sum(1 for cid in IDS if P[cid]["trigger"]["disputed"])
    print(f"cases={len(IDS)} written={n} changed_main={cm} reserve_used={ru} disputed={dp}")

if __name__ == "__main__":
    main()
